/*!
 * Full Service & Clean — Asistente virtual flotante ("Boty") con el robot 3D animado
 * Un solo archivo, sin dependencias. Se aísla con Shadow DOM, así que no choca con los estilos de tu página.
 * El robot 3D va incluido (3 capas WebP en base64) y se anima en SVG: flota, te mira con el "ojo" (visor con código),
 * saluda con el brazo, piensa mientras escribe la respuesta y hace pulgar arriba cuando confirma algo.
 *
 * USO (pegar antes de </body>):
 *   <script src="/fsc-assistant.js" defer
 *           data-whatsapp="5959XXXXXXXX"
 *           data-position="right"><\/script>
 *
 * Opciones (atributos data-* o window.FSC_ASSISTANT_CONFIG = {...} antes de cargar el script):
 *   whatsapp, address, hours, businessName, position ('right'|'left'), demo (true|false),
 *   sound (true|false), autoGreet (true|false), loadFonts (true|false), avatar (URL de imagen para el icono chico del chat)
 *
 * API:   FSCAssistant.open() · .close() · .toggle() · .say('texto') · .destroy()
 * Hook:  window.FSC_onBooking = data => fetch('/api/turnos', { method:'POST', body: JSON.stringify(data) })
 */
(function () {
'use strict';
if (window.FSCAssistant) return;

/* Imagen de Boty (recorte del render 3D), embebida para que el archivo sea autosuficiente. */
const DEFAULT_AVATAR = 'data:image/jpeg;base64,';

/* Robot 3D por capas (recorte de tu render): cuerpo, cabeza sin emblema y antebrazo con el pulgar. */
const IMG = {
    base: 'data:image/webp;base64,',
    head: 'data:image/webp;base64,',
    arm:  'data:image/webp;base64,'
};

/* =====================================================================
   CONFIGURACIÓN — valores por defecto (se pueden sobrescribir desde fuera)
   ===================================================================== */
const DEFAULTS = {
    businessName: 'Full Service & Clean',
    botName: 'Boty',
    whatsapp: '',      // código de país + número, sin + ni espacios. Vacío = sin botón de WhatsApp.
    address: '',       // Vacío = el bot pide contactar al taller para la ubicación.
    hours: 'Lunes a viernes 07:30 – 17:30 · Sábados 08:00 – 12:00',   // EJEMPLO: reemplazar por el horario real
    position: 'right', // 'right' | 'left'
    demo: true,        // true = muestra avisos de "modo demostración". Poner false en producción.
    sound: true,       // efectos de sonido (solo suenan tras una interacción del usuario)
    autoGreet: true,   // el robot saluda solo una vez por sesión
    loadFonts: true,   // carga Orbitron/Rajdhani/Inter desde Google Fonts (si no, usa fuentes del sistema)
    avatar: ''         // URL de una imagen cuadrada para el icono chico del chat (cabecera y mensajes). Vacío = la cara de Boty incluida.
};

/* ⚠ PRECIOS Y TIEMPOS DE EJEMPLO: reemplazar por los valores reales del taller.
   `re` se prueba contra el texto del usuario (minúsculas, sin tildes). `pri` desempata. */
const SERVICES = [
    { id: 'aceite',     group: 'mant', short: 'Cambio de aceite',  name: 'Cambio de aceite y filtros',       from: 'Gs. 250.000', time: '45 min', re: /aceite|filtro|lubric/ },
    { id: 'frenos',     group: 'mant', short: 'Frenos',            name: 'Revisión y cambio de frenos',      from: 'Gs. 350.000', time: '2 h',    re: /freno|pastilla/ },
    { id: 'motor',      group: 'mant', short: 'Diagnóstico motor', name: 'Diagnóstico de motor (scanner)',   from: 'Gs. 180.000', time: '1 h',    re: /diagnost|scanner|escaner|check engine|motor/ },
    { id: 'alineacion', group: 'mant', short: 'Alineación',        name: 'Alineación y balanceo',            from: 'Gs. 200.000', time: '1 h',    re: /alinea|balanceo|neumatic|cubierta|goma/ },
    { id: 'lavado',     group: 'det',  short: 'Lavado VIP',        name: 'Lavado VIP completo',              from: 'Gs. 120.000', time: '1 h 30', re: /\bvip\b|lavado|lavar/ },
    { id: 'pulido',     group: 'det',  short: 'Pulido y encerado', name: 'Pulido y encerado',                from: 'Gs. 450.000', time: '4 h',    re: /pulid|encer|cera|ceramic/, pri: 1 },
    { id: 'interior',   group: 'det',  short: 'Interior',          name: 'Limpieza de tapizados e interior', from: 'Gs. 300.000', time: '3 h',    re: /interior|tapiz|asiento/, pri: 1 },
    { id: 'chasis',     group: 'det',  short: 'Lavado de chasis',  name: 'Lavado de chasis y motor',         from: 'Gs. 150.000', time: '1 h',    re: /chasis/, pri: 2 }
];

const STATUS_STEPS = ['Recibido', 'Diagnóstico', 'En proceso', 'Control de calidad', 'Listo para retirar'];

/* Órdenes de demostración. En producción reemplaza `lookupOrder` por una llamada a tu API/ERP. */
const DEMO_ORDERS = {
    ABC123: { vehicle: 'Toyota Hilux 2019', service: 'Cambio de aceite y frenos', step: 2, eta: 'Hoy, 16:30' },
    XYZ789: { vehicle: 'Kia Sportage 2021', service: 'Lavado VIP completo',      step: 4, eta: 'Ya puedes retirarlo' }
};
function lookupOrder(plate) { return DEMO_ORDERS[plate] || null; }

const MENU = ['🔧 Agendar cita', '🧼 Lavado & Detailing', '📋 Estado de mi auto', '💲 Precios', '🕒 Horarios'];
const WAVE_LINES = ['¡Hola! 👋', '¿Necesitas ayuda?', '¡A tu servicio! 🔧'];

/* Lee opciones desde los atributos data-* del <script> */
function readScriptOptions() {
    const s = document.currentScript || document.querySelector('script[data-fsc-assistant], script[src*="fsc-assistant"]');
    const out = {};
    if (!s || !s.dataset) return out;
    const bool = v => v === 'true' || v === '' || v === '1';
    Object.keys(DEFAULTS).forEach(k => {
        if (s.dataset[k] === undefined) return;
        out[k] = typeof DEFAULTS[k] === 'boolean' ? bool(s.dataset[k]) : s.dataset[k];
    });
    return out;
}
const CONFIG = Object.assign({}, DEFAULTS, window.FSC_ASSISTANT_CONFIG || {}, readScriptOptions());
CONFIG.avatar = CONFIG.avatar || DEFAULT_AVATAR;

/* =====================================================================
   ICONOS (SVG en línea, sin librerías)
   ===================================================================== */
const ICON = {
    wrench:   '<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>',
    send:     '<path d="M22 2 11 13"/><path d="M22 2 15 22l-4-9-9-4 20-7z"/>',
    x:        '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>',
    volOn:    '<path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M19 5a10 10 0 0 1 0 14"/>',
    volOff:   '<path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="m22 9-6 6"/><path d="m16 9 6 6"/>',
    reset:    '<path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/>',
    bot:      '<rect x="4" y="8" width="16" height="12" rx="3"/><path d="M12 8V5"/><circle cx="12" cy="4" r="1"/><path d="M9 14h.01M15 14h.01"/>',
    car:      '<path d="M19 17h2a1 1 0 0 0 1-1v-3a2 2 0 0 0-1.5-1.9C18.7 10.6 16 10 16 10s-1.3-1.4-2.2-2.3A2.5 2.5 0 0 0 12 7H5a1.5 1.5 0 0 0-1.4.9L2.2 10.8A3.7 3.7 0 0 0 2 12v4a1 1 0 0 0 1 1h2"/><circle cx="7" cy="17" r="2"/><path d="M9 17h6"/><circle cx="17" cy="17" r="2"/>',
    calendar: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
    user:     '<path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',
    check:    '<circle cx="12" cy="12" r="9"/><path d="m9 12 2 2 4-4"/>',
    circle:   '<circle cx="12" cy="12" r="9"/>',
    spinner:  '<path d="M21 12a9 9 0 1 1-6.2-8.55"/>',
    chat:     '<path d="M7.9 20A9 9 0 1 0 4 16.1L2 22z"/><path d="M9 10c.5 2 2 3.5 4 4l1.5-1.5 2 1-.5 1.5c-2.5.5-6.5-2-7-6.5l1.5-.5 1 2z"/>'
};
const icon = (name, cls) => '<svg class="ico' + (cls ? ' ' + cls : '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + ICON[name] + '</svg>';

/* =====================================================================
   ESTILOS (dentro del Shadow DOM)
   ===================================================================== */
const CSS = `
:host { all: initial; }
*, *::before, *::after { box-sizing: border-box; }
.root {
    position: fixed; bottom: 16px; right: 16px; z-index: 2147483000;
    display: flex; flex-direction: column; align-items: flex-end; gap: 10px;
    font: 400 13px/1.45 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
    color: #E2E8F0; pointer-events: none;
    /* El estilo del sitio anfitrión hereda dentro del Shadow DOM: se neutraliza lo que suele filtrarse */
    letter-spacing: normal; word-spacing: normal; text-transform: none; text-indent: 0; text-align: left; text-shadow: none;
    font-style: normal; font-variant: normal; white-space: normal; direction: ltr; cursor: auto; visibility: visible;
}
.root.left { right: auto; left: 16px; align-items: flex-start; }
.root > * { pointer-events: auto; }
button { font: inherit; color: inherit; cursor: pointer; }
button:focus-visible, input:focus-visible, a:focus-visible, .robot:focus-visible { outline: 2px solid #00A8FF; outline-offset: 2px; }
.ico { width: 1em; height: 1em; flex: none; vertical-align: -0.125em; }
b { color: #fff; }
.spin { animation: spin 1.2s linear infinite; transform-origin: center; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Panel de chat ---------- */
.panel {
    display: none; flex-direction: column; overflow: hidden;
    width: 370px; max-width: calc(100vw - 32px);
    height: min(520px, calc(100vh - 250px)); min-height: 320px;
    background: rgba(12, 22, 40, 0.97);
    border: 1px solid rgba(0, 168, 255, 0.4); border-radius: 18px;
    box-shadow: 0 18px 50px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(0,0,0,.3);
}
.root.open .panel { display: flex; animation: panelIn 0.25s cubic-bezier(0.2, 0.9, 0.3, 1.2); transform-origin: bottom right; }
.root.left.open .panel { transform-origin: bottom left; }
@keyframes panelIn { from { opacity: 0; transform: translateY(14px) scale(0.96); } to { opacity: 1; transform: none; } }

.ph { display: flex; align-items: center; gap: 10px; padding: 12px 12px 12px 14px; background: #0A192F; border-bottom: 1px solid rgba(0, 168, 255, 0.3); }
.ph-av { position: relative; width: 38px; height: 38px; flex: none; }
.ph-av img, .av img { display: block; width: 100%; height: 100%; border-radius: 50%; object-fit: cover; border: 1px solid #00A8FF; }
.ph-av::after { content: ''; position: absolute; right: 0; bottom: 0; width: 10px; height: 10px; border-radius: 50%; background: #00FF66; border: 2px solid #0A192F; box-shadow: 0 0 6px #00FF66; }
.ph-t { flex: 1; min-width: 0; }
.ph-t h3 { margin: 0; font: 800 13px 'Orbitron', system-ui, sans-serif; letter-spacing: .04em; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ph-t p { margin: 2px 0 0; font: 10px ui-monospace, SFMono-Regular, Menlo, monospace; color: #00A8FF; letter-spacing: .04em; }
.ph-btn { width: 30px; height: 30px; flex: none; display: flex; align-items: center; justify-content: center; border: 0; border-radius: 8px; background: transparent; color: #94A3B8; font-size: 16px; }
.ph-btn:hover { background: rgba(255,255,255,.08); color: #fff; }

.msgs { flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 14px; display: flex; flex-direction: column; gap: 12px; }
.msgs::-webkit-scrollbar { width: 6px; }
.msgs::-webkit-scrollbar-track { background: rgba(10, 25, 47, 0.5); }
.msgs::-webkit-scrollbar-thumb { background: #00A8FF88; border-radius: 3px; }
.row { display: flex; align-items: flex-start; gap: 10px; }
.row.user { justify-content: flex-end; }
.av { width: 30px; height: 30px; flex: none; }
.msg { max-width: 85%; padding: 10px 12px; border-radius: 16px 16px 16px 0; background: rgba(42, 59, 80, 0.6); border: 1px solid rgba(0, 168, 255, 0.2); overflow-wrap: anywhere; }
.row.user .msg { background: rgba(0, 168, 255, 0.2); border-color: rgba(0, 168, 255, 0.4); color: #fff; border-radius: 16px 16px 0 16px; }
.msg.typing { display: flex; gap: 4px; padding: 13px 12px; }
.dot { width: 5px; height: 5px; border-radius: 50%; background: #00A8FF; animation: bounce 1s ease-in-out infinite; }
.dot:nth-child(2) { animation-delay: .15s; } .dot:nth-child(3) { animation-delay: .3s; }
@keyframes bounce { 0%, 60%, 100% { transform: translateY(0); opacity: .5; } 30% { transform: translateY(-4px); opacity: 1; } }

.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.chip { padding: 5px 10px; border-radius: 999px; border: 1px solid rgba(0,168,255,.45); background: rgba(0,168,255,.1); color: #00A8FF; font-size: 12px; transition: background .15s; }
.chip:hover:not(:disabled) { background: rgba(0,168,255,.25); }
.chip:disabled { opacity: .45; cursor: default; }
.chip.picked { background: rgba(0,168,255,.35); color: #fff; opacity: 1; }

.sec { margin: 10px 0 2px; color: #00A8FF; font-weight: 600; }
.prow { display: flex; justify-content: space-between; gap: 12px; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,.06); }
.prow em { font-style: normal; font-weight: 600; color: #FF6B00; white-space: nowrap; }
.mut { color: #94A3B8; }
.list { margin: 8px 0 0; padding: 0; list-style: none; }
.list li { margin: 3px 0; }
.summary { margin-top: 6px; padding: 10px; display: grid; gap: 5px; border-radius: 12px; background: rgba(10,25,47,.65); border: 1px solid rgba(0,168,255,.2); }
.summary .ico { color: #FF6B00; margin-right: 4px; }
.tl { margin: 8px 0 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.tl li { display: flex; align-items: center; gap: 8px; color: #6B7280; }
.tl li.done { color: #D1D5DB; } .tl li.done .ico { color: #4ADE80; }
.tl li.cur { color: #fff; font-weight: 600; } .tl li.cur .ico { color: #FF6B00; }
.eta { margin-top: 8px; font-weight: 600; color: #FF6B00; }
.note { margin-top: 8px; font: 10px ui-monospace, SFMono-Regular, Menlo, monospace; color: rgba(255,107,0,.85); }
.wa-btn { display: inline-flex; align-items: center; gap: 6px; margin-top: 8px; padding: 6px 12px; border-radius: 10px; background: rgba(34,197,94,.2); border: 1px solid rgba(74,222,128,.5); color: #86EFAC; font-weight: 600; text-decoration: none; }

.pf { display: flex; gap: 8px; padding: 10px; background: #0A192F; border-top: 1px solid rgba(0, 168, 255, 0.3); }
.pf input { flex: 1; min-width: 0; padding: 9px 12px; border-radius: 12px; border: 1px solid rgba(0,168,255,.3); background: rgba(10,25,47,.8); color: #fff; font: inherit; }
.pf input::placeholder { color: #94A3B8; }
.pf input:focus { outline: none; border-color: #00A8FF; }
.pf button { width: 38px; height: 38px; flex: none; display: flex; align-items: center; justify-content: center; border: 0; border-radius: 12px; background: linear-gradient(135deg, #00A8FF, #06B6D4); color: #fff; font-size: 16px; box-shadow: 0 4px 14px rgba(0,168,255,.3); }
.pf button:hover { opacity: .9; }

/* ---------- Lanzador: el robot 3D animado ---------- */
.mascot { --ring: #37b8ff; --glyph: #ffb347; --glow: #ff7a00; --k: 1; position: relative; width: 124px; }
.mascot.speaking { --ring: #ff9a3d; --glyph: #ffd08a; --glow: #ff6b00; }
.mascot.thumbsup { --ring: #3dffa0; --glyph: #8dffc2; --glow: #1fd67a; }
.halo { position: absolute; left: 50%; top: 56%; width: 150%; aspect-ratio: 1; transform: translate(-50%, -50%); pointer-events: none;
    background: radial-gradient(circle, rgba(0,168,255,.26) 0%, rgba(0,168,255,.07) 40%, transparent 64%); animation: haloPulse 3.2s ease-in-out infinite; }
.mascot.speaking .halo { background: radial-gradient(circle, rgba(255,120,30,.30) 0%, rgba(255,107,0,.07) 40%, transparent 64%); }
.ground { position: absolute; left: 14%; right: 14%; bottom: -2%; height: 7%; border-radius: 50%; background: radial-gradient(ellipse, rgba(0,0,0,.6), transparent 70%); animation: groundPulse 3.2s ease-in-out infinite; pointer-events: none; }
.float { position: relative; animation: float 3.2s ease-in-out infinite; }
.robot {
    position: relative; display: block; width: 100%; padding: 0; border: 0; border-radius: 22px; background: none; cursor: pointer;
    transition: transform .2s ease; -webkit-tap-highlight-color: transparent; filter: drop-shadow(0 8px 12px rgba(0,0,0,.4));
}
.robot:hover { transform: scale(1.05); }
.rig { display: block; width: 100%; height: auto; overflow: visible; pointer-events: none; }
.badge { position: absolute; top: 4%; right: 14%; width: 16px; height: 16px; border-radius: 50%; background: #FF6B00; border: 2px solid #fff; box-shadow: 0 0 8px #FF6B00; z-index: 5; animation: pulseDot 1.4s ease-in-out infinite; }
.badge[hidden] { display: none; }
.bubble {
    position: absolute; bottom: 100%; right: 0; margin-bottom: 12px; width: max-content; max-width: min(240px, calc(100vw - 48px));
    padding: 8px 14px; border-radius: 16px; background: #FF6B00; color: #fff; text-align: center;
    font: 700 16px/1.2 'Rajdhani', system-ui, sans-serif; box-shadow: 0 0 15px rgba(255,107,0,.6);
    transform: scale(0); transform-origin: bottom right; transition: transform .3s cubic-bezier(.175,.885,.32,1.275); cursor: pointer; z-index: 40;
}
.root.left .bubble { right: auto; left: 0; transform-origin: bottom left; }
.bubble.active { transform: scale(1); }
.bubble::after { content: ''; position: absolute; bottom: -8px; right: 52px; border: 8px solid transparent; border-bottom: 0; border-top-color: #FF6B00; }
.root.left .bubble::after { right: auto; left: 44px; }

/* Rig del robot: cabeza (JS) y brazo (CSS) se mueven por separado del cuerpo */
.g-lean { transform-origin: 200px 172px; will-change: transform; }
.g-eyes { will-change: transform; }
.g-arm { transform-origin: 343px 248px; animation: armSway 5s ease-in-out infinite; }

/* "Ojo": visor con código cayendo, escáner y anillos HUD */
.emb-glow { fill: var(--ring); opacity: .3; transition: opacity .15s, fill .2s; }
.emb-ring  { fill: none; stroke: var(--ring); stroke-width: 6; transition: stroke .2s; }
.emb-ring2 { fill: none; stroke: var(--ring); stroke-width: 1.5; stroke-opacity: .5; stroke-dasharray: 14 6; transform-box: fill-box; transform-origin: center; animation: spin 16s linear infinite reverse; transition: stroke .2s; }
.hud-a { fill: none; stroke: var(--ring); stroke-width: 3; stroke-dasharray: 1.6 9; opacity: .75; transform-box: fill-box; transform-origin: center; animation: spin 26s linear infinite; transition: stroke .2s; }
.spin-arc { fill: none; stroke: var(--ring); stroke-width: 4; stroke-linecap: round; stroke-dasharray: 60 300; opacity: 0; transform-box: fill-box; transform-origin: center; transition: opacity .2s; }
.rain { opacity: .55; }
.rain text { fill: var(--ring); font: 700 9px ui-monospace, SFMono-Regular, Menlo, Consolas, 'Courier New', monospace; text-anchor: middle; transition: fill .2s; }
.rain-col { animation: rainFall linear infinite; animation-duration: calc(var(--d) * var(--k)); }
.scan { fill: var(--ring); opacity: .55; animation: scan 3.2s ease-in-out infinite; }
.halo-use { fill: var(--glow); stroke: var(--glow); opacity: .9; }
.core-use { fill: var(--glyph); stroke: var(--glyph); }
.glyph { opacity: 0; transition: opacity .18s ease; }
.gl-wrench { opacity: 1; }
.mascot[data-face="code"] .gl-wrench { opacity: 0; }
.mascot[data-face="code"] .gl-code { opacity: 1; }
.mascot.blink .gl-wrench, .mascot.blink[data-face="code"] .gl-code { opacity: .2; }

.mascot.thinking { --k: .4; }
.mascot.thinking .spin-arc { opacity: 1; animation: spin .9s linear infinite; }
.mascot.speaking .emb-glow { opacity: .75; }
.mascot.waving .g-arm { animation: armWave 1.3s ease-in-out 2 both; }
.mascot.hello .g-arm { animation: armWave 1.3s ease-in-out 1 both; }
.mascot.thumbsup .float { animation: hop .6s ease-out 2; }
.mascot.thumbsup .g-arm { animation: thumbs .9s ease 1 both; }
.mascot.thumbsup .glyph:not(.gl-check) { opacity: 0; }
.mascot.thumbsup .gl-check { opacity: 1; }
.mascot.thumbsup .emb-glow { opacity: .85; }

@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }
@keyframes haloPulse { 0%, 100% { opacity: .75; } 50% { opacity: 1; } }
@keyframes groundPulse { 0%, 100% { transform: scaleX(1); opacity: 1; } 50% { transform: scaleX(.88); opacity: .7; } }
@keyframes pulseDot { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.25); } }
@keyframes hop { 0%, 100% { transform: translateY(0); } 40% { transform: translateY(-16px) scale(1.04); } }
@keyframes armSway { 0%, 100% { transform: rotate(-1.4deg); } 50% { transform: rotate(1.8deg); } }
@keyframes armWave { 0%, 100% { transform: rotate(0); } 20% { transform: rotate(-16deg); } 45% { transform: rotate(10deg); } 70% { transform: rotate(-14deg); } 90% { transform: rotate(6deg); } }
@keyframes thumbs { 0% { transform: rotate(0); } 30% { transform: rotate(-16deg); } 60% { transform: rotate(7deg); } 80% { transform: rotate(-6deg); } 100% { transform: rotate(0); } }
@keyframes rainFall { from { transform: translateY(-160px); } to { transform: translateY(0); } }
@keyframes scan { 0% { transform: translateY(-46px); opacity: 0; } 15%, 85% { opacity: .6; } 100% { transform: translateY(46px); opacity: 0; } }

/* ---------- Móvil: el panel ocupa casi toda la pantalla y la mascota se oculta ---------- */
@media (max-width: 520px) {
    .root { bottom: 10px; right: 10px; }
    .root.left { left: 10px; }
    .root.open { left: 8px; right: 8px; bottom: 8px; align-items: stretch; }
    .root.open .panel { width: auto; max-width: none; height: min(82vh, 640px); height: min(82dvh, 640px); }
    .root.open .mascot { display: none; }
    .mascot { width: 96px; }
    .pf input { font-size: 16px; }
}
@media (prefers-reduced-motion: reduce) {
    .mascot *, .halo, .ground, .badge, .dot, .spin { animation: none !important; }
    .root.open .panel { animation: none; }
}
`;

/* =====================================================================
   ROBOT 3D (SVG con las capas de imagen + "ojo" vectorial)
   ===================================================================== */
const rainMarkup = () => {
    const chars = '01<>/{}();=+*#$[]&|', ent = c => (c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '&' ? '&amp;' : c), xs = [-32, -19, -6.5, 6.5, 19, 32];
    return xs.map((x, i) => {
        let col = '';
        for (let r = 0; r < 16; r++) col += '<tspan x="' + x + '" dy="' + (r ? 10 : 0) + '">' + ent(chars[Math.floor(Math.random() * chars.length)]) + '</tspan>';
        const d = (2.6 + (i * 0.37) % 1.9).toFixed(2), delay = (-(i * 0.9) % 3).toFixed(2);
        return '<g class="rain-col" style="--d:' + d + 's;animation-delay:' + delay + 's"><text y="-44">' + col + '</text><text y="116">' + col + '</text></g>';
    }).join('');
};
const rigMarkup = () => `
<svg class="rig" viewBox="18 6 416 516" aria-hidden="true" focusable="false">
  <defs>
    <filter id="rg-blur" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="4"/></filter>
    <filter id="rg-blur2" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="12"/></filter>
    <radialGradient id="rg-disc" cx="0.4" cy="0.32" r="0.85"><stop offset="0" stop-color="#2b71a6"/><stop offset=".6" stop-color="#173f6b"/><stop offset="1" stop-color="#0d2748"/></radialGradient>
    <clipPath id="rg-clip"><circle r="44"/></clipPath>
    <radialGradient id="rg-vign"><stop offset=".5" stop-color="#0b2242" stop-opacity="0"/><stop offset="1" stop-color="#0b2242" stop-opacity=".95"/></radialGradient>
    <g id="rg-gcode"><path fill="none" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" d="M-9 -13 L-23 0 L-9 13 M9 -13 L23 0 L9 13 M4 -17 L-4 17"/></g>
    <g id="rg-gwrench"><g transform="translate(-30 -30) scale(2.5)"><path stroke-width="1.6" stroke-linejoin="round" d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></g></g>
    <g id="rg-gcheck"><path fill="none" stroke-width="9" stroke-linecap="round" stroke-linejoin="round" d="M-20 1 L-6 15 L21 -14"/></g>
  </defs>
  <g class="g-lean">
    <image href="${IMG.head}" x="0" y="0" width="450" height="530"/>
    <g transform="translate(205 116)"><g class="g-eyes">
      <circle class="emb-glow" r="56" filter="url(#rg-blur2)"/>
      <circle r="49" fill="url(#rg-disc)"/>
      <g clip-path="url(#rg-clip)"><g class="rain">${rainMarkup()}</g><rect class="scan" x="-44" y="-1.5" width="88" height="3"/></g>
      <circle r="44" fill="url(#rg-vign)"/>
      <circle r="27" fill="#0a1f3d" opacity=".6" filter="url(#rg-blur)"/>
      <circle class="emb-ring" r="47"/>
      <circle class="emb-ring2" r="39"/>
      <circle class="hud-a" r="53.5"/>
      <circle class="spin-arc" r="56"/>
      <g class="glyph gl-wrench"><use class="halo-use" href="#rg-gwrench" filter="url(#rg-blur)"/><use class="core-use" href="#rg-gwrench"/></g>
      <g class="glyph gl-code"><use class="halo-use" href="#rg-gcode" filter="url(#rg-blur)"/><use class="core-use" href="#rg-gcode"/></g>
      <g class="glyph gl-check"><use class="halo-use" href="#rg-gcheck" filter="url(#rg-blur)"/><use class="core-use" href="#rg-gcheck"/></g>
    </g></g>
  </g>
  <image href="${IMG.base}" x="0" y="0" width="450" height="530"/>
  <g class="g-arm"><image href="${IMG.arm}" x="0" y="0" width="450" height="530"/></g>
</svg>`;

/* =====================================================================
   MARCADO
   ===================================================================== */
const TEMPLATE = `
<div class="root" id="root">
  <section class="panel" id="panel" role="dialog" aria-label="Asistente virtual de ${'${BUSINESS}'}">
    <header class="ph">
      <div class="ph-av"><img src="{{AVATAR}}" alt=""></div>
      <div class="ph-t"><h3>${'${TITLE}'}</h3><p id="st">EN LÍNEA</p></div>
      <button class="ph-btn" id="btn-sound" type="button" aria-pressed="true" title="Sonido" aria-label="Activar o desactivar el sonido">${icon('volOn')}</button>
      <button class="ph-btn" id="btn-clear" type="button" title="Reiniciar chat" aria-label="Reiniciar chat">${icon('reset')}</button>
      <button class="ph-btn" id="btn-close" type="button" title="Cerrar" aria-label="Cerrar el asistente">${icon('x')}</button>
    </header>
    <div class="msgs" id="msgs" role="log" aria-live="polite"></div>
    <form class="pf" id="form" autocomplete="off">
      <input id="inp" type="text" maxlength="200" placeholder="Escribe tu consulta aquí..." aria-label="Escribe tu consulta">
      <button type="submit" aria-label="Enviar">${icon('send')}</button>
    </form>
  </section>

  <div class="mascot" id="mascot" data-face="wrench">
    <div class="bubble" id="bubble" role="status"></div>
    <span class="halo"></span><span class="ground"></span>
    <div class="float">
      <button class="robot" id="robot" type="button" aria-expanded="false" aria-label="Abrir asistente virtual">{{RIG}}</button>
      <span class="badge" id="badge" hidden></span>
    </div>
  </div>
</div>`;

/* =====================================================================
   UTILIDADES
   ===================================================================== */
const sleep = ms => new Promise(r => setTimeout(r, ms));
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const pick = arr => arr[Math.floor(Math.random() * arr.length)];
const esc = s => String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const norm = s => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const htmlToText = html => { const t = document.createElement('template'); t.innerHTML = html; return t.content.textContent.trim().replace(/\s+/g, ' '); };
function shorten(text) {
    const m = text.match(/^.*?[.!?](\s|$)/);
    let s = (m ? m[0] : text).trim();
    if (s.length > 70) s = s.slice(0, 67).trimEnd() + '…';
    return s;
}
function store(k, v) { try { if (v === undefined) return sessionStorage.getItem(k); sessionStorage.setItem(k, v); } catch (e) { /* almacenamiento bloqueado */ } return null; }

/* =====================================================================
   ESTADO GLOBAL DEL WIDGET (se llena en init)
   ===================================================================== */
let host, sh, $, root, panel, mascot, robot, bubble, badge, msgs, inp, statusEl, leanG, eyesG, emblemEl;
let isOpen = false, isSpeaking = false, isThinking = false, audioOn = CONFIG.sound;
let epoch = 0, chain = Promise.resolve(), pending = 0, lastActivity = Date.now();
let flow = null;   // { type: 'booking' | 'status', step, data, tries }
let bubbleTimer = null, nudgeTimer = null, nudges = 0, faceTimer = null, blinkTimer = null, faceCode = false;
const REDUCED = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const clsTimers = {};
const poke = () => { lastActivity = Date.now(); };

/* =====================================================================
   AUDIO (WebAudio, sin archivos)
   ===================================================================== */
let actx = null, unlocked = false;
function getCtx() {
    if (!audioOn || !unlocked) return null;
    try {
        actx = actx || new (window.AudioContext || window.webkitAudioContext)();
        if (actx.state === 'suspended') actx.resume();
    } catch (e) { return null; }
    return actx;
}
function tone(freq, dur, o) {
    o = o || {};
    const c = getCtx(); if (!c) return;
    const t = c.currentTime + (o.delay || 0), vol = o.vol || 0.035;
    const osc = c.createOscillator(), g = c.createGain();
    osc.type = o.type || 'square';
    osc.frequency.setValueAtTime(freq, t);
    if (o.to) osc.frequency.exponentialRampToValueAtTime(o.to, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g); g.connect(c.destination);
    osc.start(t); osc.stop(t + dur + 0.02);
}
const sfx = {
    blip() { tone(680, 0.07, { to: 980 }); tone(980, 0.08, { to: 760, delay: 0.08 }); },
    send() { tone(520, 0.06, { type: 'triangle' }); },
    wave() { [520, 660, 820].forEach((f, i) => tone(f, 0.09, { type: 'triangle', delay: i * 0.09 })); },
    ok()   { [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.12, { type: 'triangle', delay: i * 0.1 })); }
};
function toggleAudio() {
    audioOn = !audioOn;
    const b = sh.getElementById('btn-sound');
    b.innerHTML = icon(audioOn ? 'volOn' : 'volOff');
    b.setAttribute('aria-pressed', String(audioOn));
    poke();
    if (audioOn) sfx.blip();
}

/* =====================================================================
   ROBOT: gestos y burbuja
   ===================================================================== */
function restartClass(cls, ms) {
    mascot.classList.remove(cls);
    void mascot.offsetWidth;                    // reinicia la animación CSS
    mascot.classList.add(cls);
    clearTimeout(clsTimers[cls]);
    clsTimers[cls] = setTimeout(() => mascot.classList.remove(cls), ms);
}
const playWave = () => { restartClass('waving', 2700); sfx.wave(); };
const playThumbs = () => { restartClass('thumbsup', 1500); sfx.ok(); applyFace(); setTimeout(applyFace, 1600); };

/* ---- "Ojo" del robot: llave de la marca <-> </>; al pensar muestra código ---- */
function applyFace() {
    if (!mascot) return;
    const busy = isSpeaking || mascot.classList.contains('thumbsup');
    const f = isThinking || (!busy && faceCode) ? 'code' : 'wrench';
    if (mascot.getAttribute('data-face') !== f) mascot.setAttribute('data-face', f);
}
function blinkLoop() {
    blinkTimer = setTimeout(() => {
        if (!REDUCED && !isThinking && !isSpeaking) {
            mascot.classList.add('blink'); setTimeout(() => mascot.classList.remove('blink'), 130);
        }
        blinkLoop();
    }, 2600 + Math.random() * 3000);
}

/* ---- Mirada: cabeza y ojo siguen al cursor (con el chat abierto miran al chat) ---- */
const GZ = { cur: { x: 0, y: 0, hx: 0, hy: 0, hr: 0 }, tgt: { x: 0, y: 0, hx: 0, hy: 0, hr: 0 }, raf: 0, pointer: null };
function retarget() {
    if (!emblemEl) return;
    const r = emblemEl.getBoundingClientRect();
    if (!r.width) return;
    const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
    let px = null, py = null;
    if (isOpen) { const p = panel.getBoundingClientRect(); px = p.left + p.width / 2; py = p.top + p.height * 0.4; }
    else if (GZ.pointer && !REDUCED) { px = GZ.pointer.x; py = GZ.pointer.y; }
    const t = GZ.tgt;
    if (px === null) { t.x = t.y = t.hx = t.hy = t.hr = 0; }
    else {
        const dx = px - cx, dy = py - cy, dist = Math.hypot(dx, dy) || 1, f = Math.min(1, dist / 240);
        const nx = dx / dist * f, ny = dy / dist * f;
        t.x = nx * 15; t.y = ny * 9; t.hx = nx * 6; t.hy = ny * 3.5; t.hr = nx * 3.5;
    }
    kickGaze();
}
function gazeTick() {
    GZ.raf = 0;
    const k = REDUCED ? 1 : 0.14; let delta = 0;
    for (const key in GZ.cur) { const d = GZ.tgt[key] - GZ.cur[key]; GZ.cur[key] += d * k; delta = Math.max(delta, Math.abs(d)); }
    eyesG.style.transform = 'translate(' + GZ.cur.x.toFixed(2) + 'px,' + GZ.cur.y.toFixed(2) + 'px)';
    leanG.style.transform = 'translate(' + GZ.cur.hx.toFixed(2) + 'px,' + GZ.cur.hy.toFixed(2) + 'px) rotate(' + GZ.cur.hr.toFixed(2) + 'deg)';
    if (delta > 0.02) GZ.raf = requestAnimationFrame(gazeTick);
}
function kickGaze() { if (!GZ.raf) GZ.raf = requestAnimationFrame(gazeTick); }

function say(text, ms) {
    sfx.blip();
    isSpeaking = true; mascot.classList.add('speaking'); applyFace();
    clearTimeout(bubbleTimer);
    if (!isOpen) { bubble.textContent = text; bubble.classList.add('active'); }   // con el chat abierto no hace falta globo
    bubbleTimer = setTimeout(hideBubble, ms || Math.max(2400, text.length * 65));
}
function hideBubble() {
    bubble.classList.remove('active');
    mascot.classList.remove('speaking');
    isSpeaking = false; applyFace();
}
function refreshStatus() {
    statusEl.textContent = isThinking ? 'ESCRIBIENDO…' : 'EN LÍNEA';
    mascot.classList.toggle('thinking', isThinking); applyFace();
}

/* =====================================================================
   ABRIR / CERRAR
   ===================================================================== */
function openChat() {
    if (isOpen) return;
    isOpen = true; poke();
    root.classList.add('open');
    robot.setAttribute('aria-expanded', 'true');
    hideBubble(); badge.hidden = true;
    sfx.blip();
    setTimeout(() => { msgs.scrollTop = msgs.scrollHeight; inp.focus({ preventScroll: true }); retarget(); }, 60);
}
function closeChat() {
    if (!isOpen) return;
    isOpen = false; poke();
    root.classList.remove('open');
    robot.setAttribute('aria-expanded', 'false');
    robot.focus({ preventScroll: true });
    retarget();
}
const toggleChat = () => (isOpen ? closeChat() : openChat());

function robotClick() {
    poke();
    if (!isOpen) return openChat();
    playWave();                                   // con el chat abierto, la mascota solo saluda
}

/* Saludo inicial y "guiños" ocasionales para llamar la atención sin molestar */
function scheduleNudges() {
    nudgeTimer = setInterval(() => {
        if (isOpen || document.hidden || nudges >= 2 || Date.now() - lastActivity < 40000) return;
        nudges++; playWave(); say(pick(WAVE_LINES));
    }, 45000);
}

/* =====================================================================
   CHAT: mensajes, escritura simulada y cola
   ===================================================================== */
const chatBusy = () => pending > 0;
function enqueue(fn) {
    pending++;
    chain = chain.then(fn).catch(err => console.error('[FSCAssistant]', err)).finally(() => { pending--; });
    return chain;
}
const scrollDown = () => { msgs.scrollTop = msgs.scrollHeight; };
let AVATAR = '';   // se arma en init() con la imagen configurada

function addUser(text) {
    const row = document.createElement('div');
    row.className = 'row user';
    const m = document.createElement('div');
    m.className = 'msg';
    m.textContent = text;                          // textContent: lo escrito por el usuario nunca se interpreta como HTML
    row.appendChild(m); msgs.appendChild(row); scrollDown();
}
function chipButton(label) {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'chip'; b.textContent = label;
    b.addEventListener('click', () => submitUser(label, b));
    return b;
}
function disableChips() { msgs.querySelectorAll('.chip').forEach(c => { c.disabled = true; }); }
function addBot(html, chips) {
    const row = document.createElement('div');
    row.className = 'row';
    row.innerHTML = AVATAR + '<div class="msg"></div>';
    const body = row.lastElementChild;
    body.innerHTML = html;
    if (chips && chips.length) {
        const wrap = document.createElement('div');
        wrap.className = 'chips';
        chips.forEach(c => wrap.appendChild(chipButton(c)));
        body.appendChild(wrap);
    }
    msgs.appendChild(row); scrollDown();
    if (!isOpen) badge.hidden = false;             // mensaje nuevo con el chat cerrado
}
function showTyping() {
    if (sh.getElementById('typing')) return;
    const row = document.createElement('div');
    row.id = 'typing'; row.className = 'row';
    row.innerHTML = AVATAR + '<div class="msg typing" aria-label="Boty está escribiendo"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div>';
    msgs.appendChild(row); scrollDown();
}
const hideTyping = () => { const t = sh.getElementById('typing'); if (t) t.remove(); };

/* opts = { chips, say (texto del globo o false), mood ('wave'|'thumbs'), delay } */
async function bot(html, opts) {
    opts = opts || {};
    const myEpoch = epoch;
    isThinking = true; refreshStatus(); showTyping();
    const text = htmlToText(html);
    await sleep(opts.delay != null ? opts.delay : clamp(380 + text.length * 7, 450, 1200));
    hideTyping(); isThinking = false; refreshStatus();
    if (myEpoch !== epoch) return;
    addBot(html, opts.chips);
    if (opts.mood === 'wave') playWave();
    if (opts.mood === 'thumbs') playThumbs();
    if (opts.say !== false) say(opts.say || shorten(text));
}

function submitUser(text, chipEl) {
    text = String(text).trim().slice(0, 300);
    if (!text) return;
    poke(); disableChips();
    if (chipEl) chipEl.classList.add('picked');
    addUser(text); sfx.send();
    enqueue(() => respond(text));
}
function showWelcome() {
    addBot('¡Hola! 🛠️ Soy <b>' + esc(CONFIG.botName) + '</b>, el robot asistente de <b>' + esc(CONFIG.businessName) + '</b>. ¿En qué puedo ayudarte hoy? Elige una opción o escríbeme.', MENU);
}
function clearChat() {
    poke(); epoch++; flow = null;
    hideTyping(); isThinking = false; refreshStatus();
    msgs.innerHTML = '';
    showWelcome();
}

/* =====================================================================
   INTENCIONES Y FLUJOS
   ===================================================================== */
const RX = {
    status:  /(estado|seguimiento|como va|placa|esta listo|ya esta listo)/,
    price:   /(precio|costo|cuesta|cuanto|cotiz|tarifa|valor|presupuesto)/,
    booking: /(agend|turno|cita|reserv|mantenim|aceite|freno|motor|alinea|balanceo|revision|diagnost|mecanic)/,
    detail:  /(lavad|detail|limpi|pulid|encer|tapiz|interior|chasis|vip)/,
    hours:   /(horario|a que hora|abren|abierto|cierran|atienden)/,
    place:   /(ubicacion|direccion|donde|mapa|llegar|quedan)/,
    contact: /(contacto|whatsapp|telefono|llamar|asesor|humano|persona|hablar)/,
    thanks:  /(gracias|genial|perfecto|excelente|buenisimo)/,
    hello:   /\b(hola|buenas|buen dia|buenos dias|buenas tardes|buenas noches|hey|ola|saludos)\b/,
    help:    /(ayuda|que puedes|que haces|opciones)/,
    cancel:  /^(cancelar|salir|menu( principal)?|inicio|volver|reiniciar)[.!]*$/
};

const demoNote = t => CONFIG.demo ? '<div class="note">' + t + '</div>' : '';
const svcSorted = [...SERVICES].sort((a, b) => (b.pri || 0) - (a.pri || 0));
const matchService = t => svcSorted.find(s => s.re.test(t)) || null;
const list = group => SERVICES.filter(s => !group || s.group === group);
const waNumber = () => String(CONFIG.whatsapp || '').replace(/\D/g, '');
const sayMenu = intro => bot(intro + '<br>¿Qué te gustaría hacer?', { chips: MENU, say: '¿Qué necesitas?' });

async function respond(raw) {
    const t = norm(raw);
    if (RX.cancel.test(t) || t.includes('cancelar')) { flow = null; return sayMenu('Listo, dejé eso de lado. 👍'); }
    if (flow) return flow.type === 'booking' ? bookingStep(raw, t) : statusStep(raw);
    return handleIntent(raw, t);
}

async function handleIntent(raw, t) {
    if (RX.status.test(t)) return beginStatus();
    if (RX.price.test(t)) return showPrices();
    if (RX.booking.test(t)) return beginBooking(t);
    if (RX.detail.test(t)) return showDetailing();
    if (RX.hours.test(t)) {
        return bot('Nuestro horario de atención es:<br><b>' + esc(CONFIG.hours) + '</b>' + demoNote('Horario de ejemplo: edita "hours".'),
            { chips: ['🔧 Agendar cita', 'Menú principal'], say: 'Este es nuestro horario 🕒' });
    }
    if (RX.place.test(t)) {
        return bot(CONFIG.address
            ? 'Nos encuentras en:<br><b>' + esc(CONFIG.address) + '</b>'
            : 'Escríbenos o llámanos y te compartimos la ubicación exacta del taller. 📍' + demoNote('Configura "address" para mostrar la dirección.'),
            { chips: ['Hablar con un asesor', 'Menú principal'], say: 'Nuestra ubicación 📍' });
    }
    if (RX.contact.test(t)) {
        const wa = waNumber();
        const link = wa
            ? '<a class="wa-btn" href="https://wa.me/' + wa + '" target="_blank" rel="noopener">' + icon('chat') + ' Abrir WhatsApp</a>'
            : demoNote('Configura "whatsapp" para mostrar el enlace directo.');
        return bot('Con gusto te conecto con un asesor del taller. 🙋' + link, { chips: ['Menú principal'], say: 'Te paso con un asesor' });
    }
    if (RX.thanks.test(t)) return bot('¡Un placer ayudarte! 🔧 Si necesitas algo más, aquí estaré.', { mood: 'thumbs', chips: MENU });
    if (RX.hello.test(t)) {
        return bot('¡Hola! 😊 Soy <b>' + esc(CONFIG.botName) + '</b>, el asistente de <b>' + esc(CONFIG.businessName) + '</b>. Puedo agendar tu cita, cotizar un lavado o consultar el estado de tu vehículo. ¿Qué necesitas?',
            { chips: MENU, mood: 'wave', say: '¡Hola! ¿En qué te ayudo?' });
    }
    if (RX.help.test(t)) return sayMenu('Esto es lo que puedo hacer por ti:');
    return bot('Mmm, no logré entender eso 🤔. Prueba con una de estas opciones o cuéntame con otras palabras qué necesitas.',
        { chips: MENU, say: 'No te entendí, ¿probamos otra vez?' });
}

/* ---------- Precios y detailing ---------- */
const priceRows = group => list(group).map(s => '<div class="prow"><span>' + esc(s.name) + '</span><em>' + esc(s.from) + '</em></div>').join('');
function showPrices() {
    return bot('Estos son nuestros <b>precios de referencia</b> (desde):' +
        '<div class="sec">🔧 Mantenimiento</div>' + priceRows('mant') +
        '<div class="sec">🧼 Detailing &amp; Clean</div>' + priceRows('det') +
        '<div class="mut" style="margin-top:8px">El valor final depende del vehículo y se confirma en el taller.</div>' +
        demoNote('Precios de ejemplo: edita SERVICES.'),
        { chips: ['🔧 Agendar cita', 'Menú principal'], say: 'Precios de referencia 💲' });
}
function showDetailing() {
    const det = list('det');
    return bot('Nuestro servicio de <b>Detailing &amp; Clean</b> deja tu vehículo como nuevo. ✨ Opciones:' +
        '<ul class="list">' + det.map(s => '<li>• <b>' + esc(s.name) + '</b> <span class="mut">(~' + esc(s.time) + ')</span></li>').join('') + '</ul>',
        { chips: det.map(s => 'Agendar ' + s.short).concat('💲 Precios'), say: 'Detailing & Clean ✨' });
}

/* ---------- Agendar cita ---------- */
function dayChips() {
    const names = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'], out = [], now = new Date();
    for (let i = 0; out.length < 4 && i < 10; i++) {
        const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i);
        if (d.getDay() === 0) continue;                                   // sin domingos
        const dd = String(d.getDate()).padStart(2, '0'), mm = String(d.getMonth() + 1).padStart(2, '0');
        out.push((i === 0 ? 'Hoy' : i === 1 ? 'Mañana' : names[d.getDay()]) + ' ' + dd + '/' + mm);
    }
    out.push('Otro día');
    return out;
}
const SLOTS = ['Mañana (08:00–12:00)', 'Tarde (14:00–17:00)', 'Lo antes posible'];

function beginBooking(t) {
    flow = { type: 'booking', step: 'service', data: {}, tries: 0 };
    const svc = matchService(t);
    if (svc) {
        flow.data.service = svc; flow.step = 'vehicle';
        return bot('¡Perfecto! <b>' + esc(svc.name) + '</b>. 🚗 ¿Qué vehículo es? (marca, modelo y año)', { say: '¿Qué vehículo es?' });
    }
    const group = RX.detail.test(t) ? 'det' : /mantenim/.test(t) ? 'mant' : null;
    return bot('¡Con gusto! ¿Qué servicio necesitas?', { chips: list(group).map(s => s.short), say: '¿Qué servicio necesitas?' });
}
function bookingSummary(d) {
    return '<div class="summary">' +
        '<div>' + icon('wrench') + esc(d.service.name) + '</div>' +
        '<div>' + icon('car') + esc(d.vehicle) + '</div>' +
        '<div>' + icon('calendar') + esc(d.day) + ' · ' + esc(d.slot) + '</div>' +
        '<div>' + icon('user') + esc(d.name) + ' · ' + esc(d.phone) + '</div></div>';
}
async function bookingStep(raw, t) {
    const d = flow.data, text = raw.trim();
    switch (flow.step) {
        case 'service': {
            const svc = matchService(t);
            if (svc) {
                d.service = svc; flow.step = 'vehicle';
                return bot('Anotado: <b>' + esc(svc.name) + '</b>. 🚗 ¿Qué vehículo es? (marca, modelo y año)', { say: '¿Qué vehículo es?' });
            }
            if (++flow.tries >= 2 && text.length >= 4) {                  // segundo intento: se acepta como consulta especial
                d.service = { name: 'Otro: ' + text.slice(0, 60) }; flow.step = 'vehicle';
                return bot('Lo anoto como consulta especial. 🚗 ¿Qué vehículo es? (marca, modelo y año)', { say: '¿Qué vehículo es?' });
            }
            return bot('No estoy seguro de ese servicio. Elige una opción o descríbelo con otras palabras.', { chips: list().map(s => s.short), say: 'Elige un servicio 👇' });
        }
        case 'vehicle':
            if (text.length < 3) return bot('Necesito al menos la marca y el modelo. 🚗 Ejemplo: <i>Toyota Hilux 2019</i>.', { say: 'Marca y modelo, por favor' });
            d.vehicle = text.slice(0, 60); flow.step = 'day';
            return bot('¿Para qué día quieres el turno? 📅', { chips: dayChips(), say: '¿Para qué día?' });
        case 'day':
            if (/otro dia|otra fecha/.test(t)) {
                flow.step = 'dayfree';
                return bot('Escríbeme el día que prefieres (ej: <i>viernes 25</i>).', { say: '¿Qué día prefieres?' });
            }
            d.day = text.slice(0, 40); flow.step = 'slot';
            return bot('¿En qué horario te queda mejor?', { chips: SLOTS, say: '¿En qué horario?' });
        case 'dayfree':
            d.day = text.slice(0, 40); flow.step = 'slot';
            return bot('¿En qué horario te queda mejor?', { chips: SLOTS, say: '¿En qué horario?' });
        case 'slot':
            d.slot = text.slice(0, 40); flow.step = 'name';
            return bot('¿A nombre de quién agendo el turno?', { say: '¿A nombre de quién?' });
        case 'name':
            if (text.length < 2) return bot('¿Me repites tu nombre, por favor?', { say: '¿Tu nombre?' });
            d.name = text.slice(0, 40); flow.step = 'phone';
            return bot('Gracias, <b>' + esc(d.name.split(' ')[0]) + '</b>. ¿Un teléfono o WhatsApp de contacto? 📱', { say: '¿Tu teléfono?' });
        case 'phone': {
            const digits = text.replace(/\D/g, '');
            if (digits.length < 7 || digits.length > 15) return bot('Ese número no parece válido. Escríbelo con código de área, por ejemplo <i>0981 123 456</i>.', { say: 'Revisa el número 📱' });
            d.phone = text.slice(0, 25); flow.step = 'confirm';
            return bot('<b>Revisa tu solicitud:</b>' + bookingSummary(d) + '<div style="margin-top:8px">¿Confirmo el turno?</div>',
                { chips: ['✅ Confirmar', '✏️ Empezar de nuevo', 'Cancelar'], say: 'Revisa los datos y confirma 👇' });
        }
        case 'confirm':
            if (/nuevo|cambiar|empez|corregir|editar/.test(t)) return beginBooking('');
            if (/confirm|^si\b|^ok\b|correcto|listo/.test(t)) return finishBooking();
            return bot('¿Confirmo el turno con esos datos?', { chips: ['✅ Confirmar', '✏️ Empezar de nuevo', 'Cancelar'], say: '¿Confirmo el turno?' });
    }
}
async function finishBooking() {
    const d = flow.data; flow = null;
    const data = { service: d.service.name, vehicle: d.vehicle, day: d.day, slot: d.slot, name: d.name, phone: d.phone };
    if (typeof window.FSC_onBooking === 'function') {                     // gancho opcional para enviar la solicitud a tu backend
        try { window.FSC_onBooking(data); } catch (err) { console.error('[FSCAssistant] FSC_onBooking', err); }
    }
    const summary = 'Solicitud de turno - ' + CONFIG.businessName + '\nServicio: ' + data.service + '\nVehículo: ' + data.vehicle +
        '\nDía: ' + data.day + ' (' + data.slot + ')\nNombre: ' + data.name + '\nTeléfono: ' + data.phone;
    const wa = waNumber();
    const extra = wa
        ? '<div style="margin-top:8px">Envíala por WhatsApp para que el taller la confirme:</div><a class="wa-btn" href="https://wa.me/' + wa + '?text=' + encodeURIComponent(summary) + '" target="_blank" rel="noopener">' + icon('chat') + ' Enviar por WhatsApp</a>'
        : demoNote('Modo demostración: la solicitud aún no se envía a ningún sistema. Conecta window.FSC_onBooking o "whatsapp".');
    return bot('¡Listo, <b>' + esc(d.name.split(' ')[0]) + '</b>! 🎉 Tu solicitud de turno está preparada:' + bookingSummary(d) + extra,
        { chips: ['Menú principal'], mood: 'thumbs', say: '¡Turno listo! 🎉' });
}

/* ---------- Estado del vehículo ---------- */
function beginStatus() {
    flow = { type: 'status' };
    return bot('Con gusto. Escríbeme la <b>placa</b> de tu vehículo. 🔎' + demoNote('Modo demostración: prueba con ABC123 o XYZ789.'), { say: '¿Cuál es la placa?' });
}
function timelineHtml(step) {
    const last = STATUS_STEPS.length - 1;
    return '<ol class="tl">' + STATUS_STEPS.map((s, i) => {
        const done = i < step || (step === last && i === last), cur = i === step && !done;
        return '<li class="' + (done ? 'done' : cur ? 'cur' : '') + '">' + (done ? icon('check') : cur ? icon('spinner', 'spin') : icon('circle')) + esc(s) + '</li>';
    }).join('') + '</ol>';
}
async function statusStep(raw) {
    const plate = raw.toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (plate.length < 5) return bot('La placa parece incompleta. Escríbela completa, por ejemplo <b>ABC123</b>.', { say: 'Revisa la placa 🔎' });
    flow = null;
    const o = lookupOrder(plate);
    if (!o) {
        return bot('No encontré ningún vehículo con la placa <b>' + esc(plate) + '</b>. 🤔 Verifica el dato o consulta con un asesor.',
            { chips: ['Probar otra placa', 'Hablar con un asesor', 'Menú principal'], say: 'No encuentro esa placa' });
    }
    const ready = o.step === STATUS_STEPS.length - 1;
    return bot('Encontré tu vehículo: <b>' + esc(o.vehicle) + '</b><br>' + esc(o.service) + timelineHtml(o.step) +
        '<div class="eta">' + (ready ? '✅ ' : '⏱️ Estimado: ') + esc(o.eta) + '</div>',
        { chips: ['Menú principal'], mood: ready ? 'thumbs' : undefined, say: ready ? '¡Tu vehículo está listo! ✅' : 'Tu auto está en proceso ⚙️' });
}

/* =====================================================================
   INICIALIZACIÓN
   ===================================================================== */
function init() {
    if (host) return;
    if (CONFIG.loadFonts && !document.querySelector('link[data-fsc-fonts]')) {
        const l = document.createElement('link');
        l.rel = 'stylesheet'; l.setAttribute('data-fsc-fonts', '');
        l.href = 'https://fonts.googleapis.com/css2?family=Orbitron:wght@600;800&family=Rajdhani:wght@600;700&family=Inter:wght@400;500;600&display=swap';
        document.head.appendChild(l);
    }

    host = document.createElement('div');
    host.id = 'fsc-assistant';
    sh = host.attachShadow({ mode: 'open' });
    sh.innerHTML = '<style>' + CSS + '</style>' +
        TEMPLATE.replace('${BUSINESS}', esc(CONFIG.businessName)).replace('${TITLE}', esc(CONFIG.botName) + ' "Full Service"').split('{{AVATAR}}').join(esc(CONFIG.avatar)).split('{{RIG}}').join(rigMarkup());
    document.body.appendChild(host);

    AVATAR = '<div class="av"><img src="' + esc(CONFIG.avatar) + '" alt=""></div>';
    $ = id => sh.getElementById(id);
    root = $('root'); panel = $('panel'); mascot = $('mascot'); robot = $('robot'); bubble = $('bubble'); badge = $('badge');
    msgs = $('msgs'); inp = $('inp'); statusEl = $('st');
    leanG = sh.querySelector('.g-lean'); eyesG = sh.querySelector('.g-eyes'); emblemEl = sh.querySelector('.emb-ring');
    if (CONFIG.position === 'left') root.classList.add('left');
    if (!audioOn) { $('btn-sound').innerHTML = icon('volOff'); $('btn-sound').setAttribute('aria-pressed', 'false'); }

    ['pointerdown', 'keydown'].forEach(ev => window.addEventListener(ev, () => { unlocked = true; }, { once: true, passive: true }));

    robot.addEventListener('click', robotClick);
    robot.addEventListener('pointerenter', e => { if (e.pointerType === 'mouse' && !isOpen && !REDUCED && !mascot.classList.contains('waving') && !mascot.classList.contains('hello')) restartClass('hello', 1400); });
    window.addEventListener('pointermove', e => { GZ.pointer = { x: e.clientX, y: e.clientY }; if (!isOpen) retarget(); }, { passive: true });
    document.documentElement.addEventListener('pointerleave', () => { GZ.pointer = null; if (!isOpen) retarget(); });
    window.addEventListener('resize', retarget);
    bubble.addEventListener('click', openChat);
    $('btn-close').addEventListener('click', closeChat);
    $('btn-clear').addEventListener('click', clearChat);
    $('btn-sound').addEventListener('click', toggleAudio);
    $('form').addEventListener('submit', e => { e.preventDefault(); const v = inp.value; inp.value = ''; submitUser(v); inp.focus({ preventScroll: true }); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && isOpen) closeChat(); });

    showWelcome();
    badge.hidden = true;

    if (CONFIG.autoGreet && !store('fsc_greeted')) {
        setTimeout(() => {
            if (isOpen) return;
            store('fsc_greeted', '1');
            playWave(); say('¡Hola! ¿Te ayudo con tu vehículo? 👋', 6000); badge.hidden = false;
        }, 2500);
    }
    scheduleNudges();
    blinkLoop();
    if (!REDUCED) faceTimer = setInterval(() => { faceCode = !faceCode; applyFace(); }, 3600);
}

window.FSCAssistant = {
    open: openChat, close: closeChat, toggle: toggleChat,
    say: t => { poke(); say(String(t)); },
    config: CONFIG,
    destroy() { clearInterval(nudgeTimer); clearInterval(faceTimer); clearTimeout(blinkTimer); cancelAnimationFrame(GZ.raf); if (host) host.remove(); host = null; delete window.FSCAssistant; }
};

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
else init();
})();